// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId, address disputeCaller) public {
        vm.assume(disputeCaller != address(0));
        bool resultBefore = c.isDisputeAllowed(assertionId, disputeCaller);
        c.assertionDisputedCallback(assertionId);
        bool resultAfter = c.isDisputeAllowed(assertionId, disputeCaller);
        assertTrue(resultBefore == true && resultAfter == true);
    }
}

